    async def list_catalog_public_plan(
        self,
        *,
        ovh_subsidiary: NichandleOvhSubsidiaryEnum,
        product_name: str,
        x_pagination_cursor: str | None = None,
        x_pagination_size: int | None = None,
        plan_code: list[str] | None = None,
    ) -> list[OrderCatalogMiddlewarePlan]:
        """
        GET /1.0/order/catalog/public/plan

        Retrieve plans from a product's catalog

        Args:
            x_pagination_cursor: Pagination cursor
            x_pagination_size: Pagination size
            ovh_subsidiary: Subsidiary of the country you want to consult plans for
            plan_code: Optional list of plan codes to fetch
            product_name: Product name whose plans you want to fetch
        """
        data = await self._client.request_json(
            "GET",
            "/1.0/order/catalog/public/plan",
            params={
                "ovhSubsidiary": ovh_subsidiary,
                "planCode": plan_code,
                "productName": product_name,
            },
            headers={
                "X-Pagination-Cursor": x_pagination_cursor,
                "X-Pagination-Size": x_pagination_size,
            },
            auth=False,
        )
        return parse(list[OrderCatalogMiddlewarePlan], data)

    async def list_catalog_public_plan_iter(
        self,
        *,
        ovh_subsidiary: NichandleOvhSubsidiaryEnum,
        product_name: str,
        x_pagination_size: int | None = None,
        plan_code: list[str] | None = None,
    ) -> AsyncIterator[OrderCatalogMiddlewarePlan]:
        """Iterate over every item of `list_catalog_public_plan`, cursor after cursor."""

        async def fetch(
            cursor: str | None,
        ) -> tuple[list[OrderCatalogMiddlewarePlan], str | None]:
            response = await self._client.request(
                "GET",
                "/1.0/order/catalog/public/plan",
                params={
                    "ovhSubsidiary": ovh_subsidiary,
                    "planCode": plan_code,
                    "productName": product_name,
                },
                headers={
                    "X-Pagination-Cursor": cursor,
                    "X-Pagination-Size": x_pagination_size,
                },
                auth=False,
            )
            items = parse(list[OrderCatalogMiddlewarePlan], response.json())
            return items, response.headers.get(NEXT_CURSOR_HEADER)

        async for entry in paginate_cursor(fetch):
            yield entry

    async def list_catalog_public_plan_all(
        self,
        *,
        ovh_subsidiary: NichandleOvhSubsidiaryEnum,
        product_name: str,
        x_pagination_size: int | None = None,
        plan_code: list[str] | None = None,
    ) -> list[OrderCatalogMiddlewarePlan]:
        """Every item of `list_catalog_public_plan`, all pages read."""
        return [
            entry
            async for entry in self.list_catalog_public_plan_iter(
                ovh_subsidiary=ovh_subsidiary,
                product_name=product_name,
                x_pagination_size=x_pagination_size,
                plan_code=plan_code,
            )
        ]

